def attach_quotes(stories):
    rows={}
    for line in DATA.splitlines():
        title,text,context,meaning,source=line.split('|')
        if source.isdigit(): source=f'https://www.gutenberg.org/ebooks/{source}'
        rows[title]=[dict(text=text.replace('\\n','\n'),context=context,meaning=meaning,source=source)]
    assert len(rows)==78
    for s in stories:
        assert s['title'] in rows,s['title']
        s['quotes']=rows.pop(s['title'])
    assert not rows
